SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, COUNT(DISTINCT a.hadm_id) AS admission_count, AVG(pc.seq_num) AS avg_procedure_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN procedureevents pe ON a.hadm_id = pe.subject_id JOIN procedures_icd pc ON pe.itemid = pc.itemid WHERE p.gender = 'F' AND p.anchor_age BETWEEN 72 AND 82 AND i.los BETWEEN 1 AND 3 AND pc.icd_code IN ('42848', '42849') GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los NULLS LAST;